/**
 * To set this up:
 * 1. Create a Google Sheet
 * 2. Extensions > Apps Script
 * 3. Use the following code:
 * 
 * function doPost(e) {
 *   var sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
 *   var data = JSON.parse(e.postData.contents);
 *   sheet.appendRow([
 *     data.name, 
 *     data.email, 
 *     data.q1, 
 *     data.q2, 
 *     data.q3, 
 *     data.q4, 
 *     data.code, 
 *     data.archetype, 
 *     new Date()
 *   ]);
 *   return ContentService.createTextOutput("Success").setMimeType(ContentService.MimeType.TEXT);
 * }
 * 
 * 4. Deploy > New Deployment > Web App (Set "Who has access" to "Anyone")
 * 5. Replace WEBHOOK_URL below with your deployment URL
 */

const WEBHOOK_URL = ''; // User should provide their App Script URL here

export const saveResultToSheet = async (data: any) => {
  if (!WEBHOOK_URL) {
    console.warn('Google Sheet Webhook URL not configured. Data not saved:', data);
    return;
  }

  try {
    await fetch(WEBHOOK_URL, {
      method: 'POST',
      mode: 'no-cors',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(data),
    });
  } catch (error) {
    console.error('Failed to save to sheet:', error);
  }
};

