interface LandingPageProps {
  onStart: (user: UserData) => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onStart }) => {
  const [formData, setFormData] = useState<UserData>({ name: '', email: '' });
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.email) {
      setError('Please provide your name and email to proceed.');
      return;
    }
    if (!/\S+@\S+\.\S+/.test(formData.email)) {
      setError('Please enter a valid email address.');
      return;
    }
    onStart(formData);
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-6 relative overflow-hidden">
      {/* Background Decorative Cards */}
      <div className="absolute top-10 -left-20 w-48 h-72 glass-card rounded-2xl rotate-[-15deg] opacity-20 hidden md:block animate-shuffle"></div>
      <div className="absolute bottom-10 -right-20 w-48 h-72 glass-card rounded-2xl rotate-[12deg] opacity-20 hidden md:block animate-shuffle"></div>

      <div className="w-full max-w-md space-y-12 relative z-10">
        <header className="text-center space-y-4">
          <div className="inline-block p-2 border border-[#d4af37]/30 rounded-full mb-4">
            <span className="text-2xl">🂡</span>
          </div>
          <h1 className="font-display text-5xl md:text-6xl gold-text tracking-tighter">
            Your Journey<br/>Begins
          </h1>
          <p className="font-poetic text-xl text-ivory/70 italic italic">
            Draw your cards. Discover your path.
          </p>
        </header>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="space-y-4">
            <div className="relative group">
              <input
                type="text"
                placeholder="Full Name"
                className="w-full bg-white/5 border border-white/10 rounded-lg p-4 font-body outline-none focus:border-[#d4af37]/50 transition-all placeholder:opacity-30"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              />
            </div>
            <div className="relative group">
              <input
                type="email"
                placeholder="Email Address"
                className="w-full bg-white/5 border border-white/10 rounded-lg p-4 font-body outline-none focus:border-[#d4af37]/50 transition-all placeholder:opacity-30"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          </div>

          {error && <p className="text-red-400 text-sm text-center font-body">{error}</p>}

          <button
            type="submit"
            className="w-full gold-gradient-bg py-5 rounded-lg text-black font-display font-bold text-lg hover:shadow-[0_0_30px_rgba(212,175,55,0.4)] transition-all transform active:scale-95 tracking-widest uppercase"
