  const handleStart = (user: UserData) => {
    setUserData(user);
    setState('quiz');
  };

  const handleQuizComplete = useCallback(async (answers: Record<number, 'A' | 'B'>) => {
    // Generate 4-letter code
    const code = QUESTIONS.map(q => {
      const choice = answers[q.id];
      return q.options[choice].code;
    }).join('');

    const archetype = ARCHETYPES[code];
    const result: QuizResult = {
      answers,
      code,
      archetype
    };

    setQuizResult(result);
    setState('results');

    // Integration: Save to Google Sheets
    if (userData) {
      await saveResultToSheet({
        name: userData.name,
        email: userData.email,
        q1: answers[1],
        q2: answers[2],
        q3: answers[3],
        q4: answers[4],
        code: code,
        archetype: archetype.name
      });
    }
  }, [userData]);

  const handleRestart = () => {
    setQuizResult(null);
    setState('landing');
  };

  return (
    <div className="min-h-screen text-ivory bg-[#0a0a0a] font-body overflow-x-hidden selection:bg-[#d4af37]/30">
      <div className="poker-texture"></div>

      {state === 'landing' && <LandingPage onStart={handleStart} />}
      {state === 'quiz' && <QuizPage onComplete={handleQuizComplete} />}
      {state === 'results' && quizResult && (
        <ResultsPage result={quizResult} onRestart={handleRestart} />
      )}
    </div>
  );
};

export default App;

