import React, { useState, useEffect } from 'react';
import { Question, UserData } from '../types';
import { QUESTIONS } from '../constants';
import PlayingCard from './PlayingCard';

interface QuizPageProps {
  onComplete: (answers: Record<number, 'A' | 'B'>) => void;
}

const QuizPage: React.FC<QuizPageProps> = ({ onComplete }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [answers, setAnswers] = useState<Record<number, 'A' | 'B'>>({});
  const [isAnimating, setIsAnimating] = useState(false);

  const currentQuestion = QUESTIONS[currentStep];

  const handleSelect = (option: 'A' | 'B') => {
    if (isAnimating) return;

    setIsAnimating(true);
    const updatedAnswers = { ...answers, [currentQuestion.id]: option };
    setAnswers(updatedAnswers);

    setTimeout(() => {
      if (currentStep < QUESTIONS.length - 1) {
        setCurrentStep(prev => prev + 1);
        setIsAnimating(false);
      } else {
        onComplete(updatedAnswers);
      }
    }, 600);
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-6 bg-poker-texture">
      <div className="w-full max-w-4xl space-y-12">
        {/* Progress */}
        <div className="text-center space-y-2">
          <p className="font-display text-xs tracking-[0.4em] gold-text opacity-50 uppercase">
            Phase {currentStep + 1} of {QUESTIONS.length}
          </p>
          <div className="w-32 h-[1px] bg-white/10 mx-auto rounded-full overflow-hidden">
            <div 
              className="h-full bg-gold-gradient-bg transition-all duration-700 ease-out"
              style={{ width: `${((currentStep + 1) / QUESTIONS.length) * 100}%` }}
            />
          </div>
        </div>

        {/* Question Area */}
        <div className={`
          flex flex-col md:flex-row gap-8 items-center justify-center
          transition-all duration-500
          ${isAnimating ? 'opacity-0 scale-95 translate-y-4' : 'opacity-100 scale-100 translate-y-0'}
        `}>
          <PlayingCard
            label="A"
            content={currentQuestion.options.A.text}
            onClick={() => handleSelect('A')}
            footer={currentQuestion.category}
          />

          <div className="hidden md:flex flex-col items-center gap-2 opacity-10">
             <div className="h-12 w-px bg-white"></div>
             <span className="font-display text-xs">OR</span>
             <div className="h-12 w-px bg-white"></div>
          </div>

          <PlayingCard
            label="B"
            content={currentQuestion.options.B.text}
            onClick={() => handleSelect('B')}
            footer={currentQuestion.category}
          />
        </div>

        <div className="text-center">
           <p className="font-heading italic text-xl text-ivory/40">Choose the card that pulls at your intuition</p>
        </div>
      </div>
    </div>
  );
};

