import React, { useState } from 'react';
import { UserData } from '../types';

interface LandingPageProps {
  onStart: (user: UserData) => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onStart }) => {
  const [formData, setFormData] = useState<UserData>({ name: '', email: '' });
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.email) {
      setError('Please provide your name and email to proceed.');
      return;
    }
    if (!/\S+@\S+\.\S+/.test(formData.email)) {
      setError('Please enter a valid email address.');
      return;
    }
    onStart(formData);
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center px-6 relative overflow-hidden">
      <div className="absolute top-10 -left-20 w-48 h-72 glass-card rounded-2xl rotate-[-15deg] opacity-20 hidden md:block animate-shuffle"></div>
      <div className="absolute bottom-10 -right-20 w-48 h-72 glass-card rounded-2xl rotate-[12deg] opacity-20 hidden md:block animate-shuffle"></div>

      <div className="w-full max-w-md space-y-12 relative z-10">
        <header className="text-center space-y-6">
          <div className="inline-block p-4 border border-[#d4af37]/30 rounded-full mb-2">
            <span className="text-3xl gold-text">🂡</span>
          </div>
          <h1 className="font-display text-5xl md:text-7xl gold-text tracking-tighter leading-none">
            Your Journey<br/>Begins
          </h1>
          <p className="font-heading italic text-xl text-ivory/80">
            Draw your cards. Discover your path.
          </p>
        </header>

        <form onSubmit={handleSubmit} className="space-y-8">
          <div className="space-y-6">
            <div className="relative">
              <input
                type="text"
                placeholder="Full Name"
                className="w-full bg-transparent border-b border-[#d4af37]/30 py-4 font-body outline-none focus:border-[#d4af37] transition-all placeholder:opacity-30 text-ivory"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              />
            </div>
            <div className="relative">
              <input
                type="email"
                placeholder="Email Address"
                className="w-full bg-transparent border-b border-[#d4af37]/30 py-4 font-body outline-none focus:border-[#d4af37] transition-all placeholder:opacity-30 text-ivory"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              />
            </div>
          </div>

          {error && <p className="text-red-400 text-sm text-center font-body">{error}</p>}

          <div className="relative group">
            <div className="absolute -inset-1 bg-gold-gradient-bg rounded-none blur opacity-25 group-hover:opacity-50 transition duration-1000 group-hover:duration-200"></div>
            <button
              type="submit"
              className="relative w-full py-5 font-display text-lg tracking-[0.3em] uppercase transition-all duration-300 border border-[#d4af37] text-[#d4af37] hover:bg-[#d4af37] hover:text-black"
            >
              Shuffle & Start
            </button>
          </div>
        </form>
      </div>

      <footer className="absolute bottom-8 text-[10px] tracking-[0.4em] opacity-30 uppercase font-body">
        Private Reading • No. 042
      </footer>
    </div>
  );
};

export default LandingPage;

