import React, { useState } from 'react';
import { QUESTIONS } from '../constants';
import PlayingCard from './PlayingCard';

interface QuizPageProps {
  onComplete: (answers: Record<number, 'A' | 'B'>) => void;
}

const QuizPage: React.FC<QuizPageProps> = ({ onComplete }) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [answers, setAnswers] = useState<Record<number, 'A' | 'B'>>({});
  const [isAnimating, setIsAnimating] = useState(false);

  const currentQuestion = QUESTIONS[currentStep];

  // Rotating suits for each phase
  const suits: ('♠' | '♥' | '♦' | '♣')[] = ['♠', '♥', '♦', '♣'];
  const currentSuit = suits[currentStep % suits.length];

  const handleSelect = (option: 'A' | 'B') => {
    if (isAnimating) return;

    setIsAnimating(true);
    const updatedAnswers = { ...answers, [currentQuestion.id]: option };
    setAnswers(updatedAnswers);

    setTimeout(() => {
      if (currentStep < QUESTIONS.length - 1) {
        setCurrentStep(prev => prev + 1);
        setIsAnimating(false);
      } else {
        onComplete(updatedAnswers);
      }
    }, 900);
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-8 bg-poker-texture">
      <div className="w-full max-w-5xl space-y-20">

        {/* Minimalist Progress Indicator */}
        <div className="text-center space-y-4">
          <p className="font-display text-[10px] uppercase tracking-[0.6em] text-accent/50">
            Observation {currentStep + 1} of {QUESTIONS.length}
          </p>
          <div className="w-32 h-[1px] bg-white/5 mx-auto relative overflow-hidden">
            <div 
              className="absolute top-0 left-0 h-full bg-accent transition-all duration-1000 ease-in-out"
              style={{ width: `${((currentStep + 1) / QUESTIONS.length) * 100}%` }}
            />
          </div>
        </div>

        {/* The Choice */}
        <div className={`
          flex flex-col md:flex-row gap-12 md:gap-20 items-center justify-center
          transition-all duration-1000 transform
          ${isAnimating ? 'opacity-0 scale-95 translate-y-12' : 'opacity-100 scale-100 translate-y-0'}
        `}>
          <PlayingCard
            label="A"
            suit={currentSuit}
            content={currentQuestion.options.A.text}
            onClick={() => handleSelect('A')}
            footer={currentQuestion.category}
          />

          <div className="flex flex-col items-center justify-center gap-4 py-8 md:py-0">
             <div className="h-20 w-[1px] bg-accent/10"></div>
             <span className="font-accent text-accent/20 text-2xl lowercase italic">or</span>
             <div className="h-20 w-[1px] bg-accent/10"></div>
          </div>

          <PlayingCard
            label="B"
            suit={currentSuit}
            content={currentQuestion.options.B.text}
            onClick={() => handleSelect('B')}
            footer={currentQuestion.category}
          />
        </div>

        <div className="text-center">
           <p className="font-script text-3xl text-white/10 italic select-none">Which card feels like the truth?</p>
        </div>
      </div>
    </div>
  );
};

export default QuizPage;

